// Redis cache with TTL and invalidation
const cache = new Redis({
  host: process.env.REDIS_HOST,
  port: process.env.REDIS_PORT,
  retryDelayOnFailover: 100
  maxRetriesPerRequest: 3
});

// Cache key pattern
const cacheKey = `user:${userId}:profile:${profileId}`;
const cacheTTL = 300; // 5 minutes

// Get with cache
async function getUserProfile(userId, profileId) {
  const key = `user:${userId}:profile:${profileId}`;
  const cached = await cache.get(key);
  if (cached) return JSON.parse(cached);

  // Cache miss - fetch from database
  const profile = await db.query(
    'SELECT * FROM user_profiles WHERE user_id = ? AND profile_id = ?',
    [userId, profileId]
  );

  // Set cache with TTL
  await cache.setex(key, JSON.stringify(profile), 'EX', cacheTTL);
  return profile;
}

// PostgreSQL connection pool
const { Pool } = require('pg').Pool;
const pool = new Pool({
  host: process.env.DB_HOST,
  port: process.env.DB_PORT,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  max: 20, // Maximum number of connections
  min: 5,  // Minimum number of connections
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 5000,
});

// Using connection pool
async function queryDatabase(sql, params) {
  const client = await pool.connect();
  try {
    const result = await client.query(sql, params);
    return result;
  } finally {
    client.release();
  }
}

// Synchronous file processing (blocking)
function processFileSync(filePath) {
  const data = fs.readFileSync(filePath);
  // Process data synchronously
  return processData(data);
}

// Asynchronous file processing (non-blocking)
async function processFileAsync(filePath) {
  const data = await fs.readFile(filePath);
  // Process data asynchronously
  return processData(data);
}

// Batch processing for multiple files
async function processBatchFiles(filePaths) {
  const promises = filePaths.map(path => processFileAsync(path));
  return Promise.all(promises);
}

// React lazy loading example
const LazyComponent = React.lazy(() => import('./HeavyComponent'));

// Dynamic import with code splitting
const loadModule = async (moduleName) => {
  const module = await import(`./modules/${moduleName}.js`);
  return module;
};

// Intersection Observer for lazy loading
const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      const lazyComponent = entry.target.dataset.lazyComponent;
      if (lazyComponent && !entry.target.dataset.loaded) {
        import(lazyComponent).then(() => {
          entry.target.dataset.loaded = 'true';
        });
      }
    }
  });
});

observer.observe(document.querySelectorAll('.lazy-load'));

// Load test configuration
