// Application Performance Monitoring (APM)
const apm = require('elastic-apm-node');

apm.startTransaction('user-request', {
  userId: req.user.id,
  operation: req.operation
});

// Custom metrics collection
const histogram = new prometheus.Histogram({
  name: 'api_response_time_seconds',
  help: 'API response time in seconds',
  buckets: [0.1, 0.25, 0.5, 1, 2.5, 5, 10]
});

// Real User Monitoring (RUM)
const rumConfig = {
  apiKey: process.env.RUM_API_KEY,
  sampleRate: 0.1, // 10% of users
  trackResources: ['js', 'css', 'images'],
  trackInteractions: ['click', 'scroll', 'form-submit']
};

// Infrastructure monitoring
const systemMetrics = {
  cpu: () => os.cpus(),
  memory: () => os.totalmem() - os.freemem(),
  disk: () => fs.statSync('/').size,
  network: () => require('system-network-stats')
};

// Node.js built-in profiler
const profiler = require('v8-profiler-next');

profiler.startProfiling('CPU');

// Profile specific function
function expensiveOperation() {
  profiler.startProfiling('CPU');
  // ... expensive operations ...
  profiler.stopProfiling('CPU');
}

// Chrome DevTools profiling
console.profile('Starting profile');
// ... operations to profile ...
console.profileEnd();

// Memory profiling
if (process.env.NODE_ENV === 'development') {
  const heapdump = require('heapdump');
  heapdump.writeSnapshot('./heapdump-' + Date.now() + '.heapsnapshot');
}
